import{_ as e,C as n,c as i,o as t,a0 as a,b as l,w as r,a as o,G as s,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Sessiehandleiding: Introductie tot de mentale speltechniek (2-3 uur)","description":"","frontmatter":{},"headers":[],"relativePath":"nl/mental-journey/session-guide.md","filePath":"nl/mental-journey/session-guide.md"}');const p=e({name:"nl/mental-journey/session-guide.md"},[["render",function(e,u,p,g,h,c){const m=n("Mermaid");return t(),i("div",null,[u[1]||(u[1]=a('<h1 id="sessiehandleiding-introductie-tot-de-mentale-speltechniek-2-3-uur" tabindex="-1">Sessiehandleiding: Introductie tot de mentale speltechniek (2-3 uur) <a class="header-anchor" href="#sessiehandleiding-introductie-tot-de-mentale-speltechniek-2-3-uur" aria-label="Permalink to &quot;Sessiehandleiding: Introductie tot de mentale speltechniek (2-3 uur)&quot;">​</a></h1><h2 id="overzicht" tabindex="-1">Overzicht <a class="header-anchor" href="#overzicht" aria-label="Permalink to &quot;Overzicht&quot;">​</a></h2><p>Deze handleiding helpt je bij het geven van een introductiesessie van 2-3 uur over mentale training voor pétanque-spelers. Perfect voor coaches, clubleiders of ervaren spelers die mentale training willen introduceren bij hun team.</p><div class="tip custom-block"><p class="custom-block-title">Deze handleiding bestaat uit twee secties.</p><ul><li><strong><a href="#voor-deelnemers">Voor deelnemers</a></strong> - Wat spelers zullen leren</li><li><strong><a href="#voor-begeleiders">Voor begeleiders</a></strong> - Hoe de sessie te leiden</li></ul></div><h2 id="sneltoegang" tabindex="-1">Sneltoegang <a class="header-anchor" href="#sneltoegang" aria-label="Permalink to &quot;Sneltoegang&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sectie</th><th>Doel</th><th>Toegang</th></tr></thead><tbody><tr><td><strong>Voor deelnemers</strong></td><td>Wat kun je van de sessie verwachten?</td><td><a href="#voor-deelnemers">Sectie bekijken</a></td></tr><tr><td><strong>Voor begeleiders</strong></td><td>Volledig sessieplan en tijdschema</td><td><a href="#voor-facilitatoren">Sectie bekijken</a></td></tr><tr><td><strong>Sessiematerialen</strong></td><td>Handleidingen, dia&#39;s en werkbladen</td><td><a href="/en/mental-journey/materials">Materialen bekijken</a></td></tr><tr><td><strong>Voorbereidingschecklist</strong></td><td>Wat je moet voorbereiden vóór de sessie</td><td><a href="#voorbereiding-1-week-vooraf">Bekijk checklist</a></td></tr></tbody></table><hr><h2 id="voor-deelnemers" tabindex="-1">Voor deelnemers <a class="header-anchor" href="#voor-deelnemers" aria-label="Permalink to &quot;Voor deelnemers&quot;">​</a></h2><h3 id="wat-kun-je-verwachten" tabindex="-1">Wat kun je verwachten? <a class="header-anchor" href="#wat-kun-je-verwachten" aria-label="Permalink to &quot;Wat kun je verwachten?&quot;">​</a></h3><p>Deze sessie introduceert het mentale aspect van pétanque door middel van discussie, oefeningen en praktische technieken die je direct kunt toepassen.</p><p><strong>Je leert het volgende:</strong></p><ul><li>Waarom mentale training belangrijk is voor prestaties</li><li>Het verschil tussen &quot;technische modus&quot; en &quot;flowmodus&quot;</li><li>Hoe herken je je innerlijke criticus en hoe ga je ermee om?</li><li>Eenvoudige technieken voor drukbeheersing</li><li>Een basisroutine vóór de opname</li></ul><p><strong>Wat je nodig hebt:</strong></p><ul><li>Een open houding en de bereidheid om te delen</li><li>Notitieboekje en pen</li><li>Jouw eigen ervaringen om over te praten</li><li>2-3 uur geconcentreerde tijd</li></ul><h3 id="sessiestructuur" tabindex="-1">Sessiestructuur <a class="header-anchor" href="#sessiestructuur" aria-label="Permalink to &quot;Sessiestructuur&quot;">​</a></h3>',15)),(t(),l(d,null,{default:r(()=>[s(m,{id:"mermaid-155",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BInvoering%20%3Cbr%2F%3E%2020%20min%5D%20--%3E%20B%5BDe%20Zone%20%3Cbr%2F%3E%2040%20min%5D%0A%20%20%20%20B%20--%3E%20C%5BPauze%20%3Cbr%2F%3E%2010%20min%5D%0A%20%20%20%20C%20--%3E%20D%5BInnerlijke%20criticus%20%3Cbr%2F%3E%2040%20min%5D%0A%20%20%20%20D%20--%3E%20E%5BPraktische%20hulpmiddelen%20%3Cbr%2F%3E%2040%20min%5D%0A%20%20%20%20E%20--%3E%20F%5BIntegratie%20%3Cbr%2F%3E%2020%20min%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:r(()=>[...u[0]||(u[0]=[o(" Loading... ",-1)])]),_:1})),u[2]||(u[2]=a('<h3 id="belangrijke-concepten-die-je-zult-onderzoeken" tabindex="-1">Belangrijke concepten die je zult onderzoeken <a class="header-anchor" href="#belangrijke-concepten-die-je-zult-onderzoeken" aria-label="Permalink to &quot;Belangrijke concepten die je zult onderzoeken&quot;">​</a></h3><h4 id="_1-de-zone-stroomtoestand" tabindex="-1">1. De zone (stroomtoestand) <a class="header-anchor" href="#_1-de-zone-stroomtoestand" aria-label="Permalink to &quot;1. De zone (stroomtoestand)&quot;">​</a></h4><ul><li>Hoe het voelt als alles op zijn plek valt.</li><li>Waarom nadenken over techniek de prestaties verstoort</li><li>De &quot;omschakeling&quot; van planning naar uitvoering.</li></ul><h4 id="_2-de-innerlijke-criticus" tabindex="-1">2. De innerlijke criticus <a class="header-anchor" href="#_2-de-innerlijke-criticus" aria-label="Permalink to &quot;2. De innerlijke criticus&quot;">​</a></h4><ul><li>Hoe negatieve zelfpraat de prestaties beïnvloedt</li><li>Het verschil tussen een innerlijke criticus en een innerlijke coach.</li><li>Neutrale observatie versus hard oordeel</li></ul><h4 id="_3-drukreactie" tabindex="-1">3. Drukreactie <a class="header-anchor" href="#_3-drukreactie" aria-label="Permalink to &quot;3. Drukreactie&quot;">​</a></h4><ul><li>Waarom je anders speelt in een wedstrijd</li><li>Fysieke tekenen van druk</li><li>Snelle resettechnieken</li></ul><h4 id="_4-praktische-hulpmiddelen" tabindex="-1">4. Praktische hulpmiddelen <a class="header-anchor" href="#_4-praktische-hulpmiddelen" aria-label="Permalink to &quot;4. Praktische hulpmiddelen&quot;">​</a></h4><ul><li>3-ademhaling reset</li><li>Eenvoudige routine vóór de opname</li><li>Foutcorrectieprotocol</li></ul><h3 id="wat-mee-te-nemen" tabindex="-1">Wat mee te nemen <a class="header-anchor" href="#wat-mee-te-nemen" aria-label="Permalink to &quot;Wat mee te nemen&quot;">​</a></h3><p><strong>Vereist:</strong></p><ul><li>Jijzelf en jouw ervaringen</li><li>Bereidheid om deel te nemen</li></ul><p><strong>Optioneel:</strong></p><ul><li>Voorbeelden van mentale uitdagingen waarmee je te maken krijgt</li><li>Vragen over specifieke situaties</li><li>Notitieboekje voor persoonlijke aantekeningen</li></ul><h3 id="na-de-sessie" tabindex="-1">Na de sessie <a class="header-anchor" href="#na-de-sessie" aria-label="Permalink to &quot;Na de sessie&quot;">​</a></h3><p>Je ontvangt:</p><ul><li>Samenvatting van de belangrijkste concepten</li><li>Oefeningen voor deze week</li><li>Links naar gedetailleerde onderwijsmodules</li><li>Doelsjabloon voor de ontwikkeling van mentale spellen</li></ul><hr><h2 id="voor-begeleiders" tabindex="-1">Voor begeleiders <a class="header-anchor" href="#voor-begeleiders" aria-label="Permalink to &quot;Voor begeleiders&quot;">​</a></h2><h3 id="voorbereidingschecklist" tabindex="-1">Voorbereidingschecklist <a class="header-anchor" href="#voorbereidingschecklist" aria-label="Permalink to &quot;Voorbereidingschecklist&quot;">​</a></h3><p><strong>1 week van tevoren:</strong></p><ul><li>[ ] Reserveer een kamer voor 2-3 uur.</li><li>[ ] Nodig 6-12 deelnemers uit</li><li>[ ] Voeg de pagina&#39;s met materialen toe aan je bladwijzers (zie <a href="/en/mental-journey/materials">Materialen</a>)</li><li>[ ] Lees deze handleiding aandachtig door.</li><li>[ ] Bereid een flipchart of whiteboard voor.</li></ul><p><strong>1 dag van tevoren:</strong></p><ul><li>[ ] Bevestig je aanwezigheid</li><li>[ ] De ruimte inrichten (rondopstelling)</li><li>[ ] Test alle technologieën (dia&#39;s, enz.).</li><li>[ ] Materialen voorbereiden</li></ul><p><strong>1 uur van tevoren:</strong></p><ul><li>[ ] Kom vroeg aan</li><li>[ ] Plaats de stoelen in een cirkel.</li><li>[ ] Materialen klaarzetten</li><li>[ ] Centreer jezelf</li></ul><h3 id="jouw-rol-als-facilitator" tabindex="-1">Jouw rol als facilitator <a class="header-anchor" href="#jouw-rol-als-facilitator" aria-label="Permalink to &quot;Jouw rol als facilitator&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Belangrijk</p><p>Je bent <strong>geen</strong> therapeut of technisch coach. Je bent een <strong>facilitator</strong> die:</p><ul><li>Discussie over handleidingen</li><li>Creëert een veilige ruimte</li><li>Verbindt concepten met ervaring</li><li>Beheert groepsdynamiek</li></ul></div><p><strong>Belangrijkste vaardigheden:</strong></p><ul><li>Actief luisteren</li><li>Neutrale aanwezigheid</li><li>Omgaan met verschillende persoonlijkheden</li><li>Weten wanneer je verder moet gaan.</li></ul><h3 id="gedetailleerd-sessieplan" tabindex="-1">Gedetailleerd sessieplan <a class="header-anchor" href="#gedetailleerd-sessieplan" aria-label="Permalink to &quot;Gedetailleerd sessieplan&quot;">​</a></h3><hr><h4 id="deel-1-inleiding-20-minuten" tabindex="-1">Deel 1: Inleiding (20 minuten) <a class="header-anchor" href="#deel-1-inleiding-20-minuten" aria-label="Permalink to &quot;Deel 1: Inleiding (20 minuten)&quot;">​</a></h4><p><strong>Doelstellingen:</strong></p><ul><li>Creëer psychologische veiligheid</li><li>Stel de verwachtingen bij.</li><li>Maak een groepsverbinding</li></ul><p><strong>Script:</strong></p><p>&quot;Welkom allemaal. Deze sessie gaat over het mentale aspect van pétanque - de gedachten, gevoelens en patronen die je prestaties beïnvloeden.&quot;</p><p><strong>Basisregels:</strong></p><ol><li>Wat hier gedeeld wordt, blijft hier.</li><li>Geen oordeel vellen over de ervaringen van anderen</li><li>Deelname is vrijwillig.</li><li>Er bestaan geen foute antwoorden.</li></ol><p><strong>Snelle ronde:</strong> Naam, hoe lang je al speelt, en één mentale uitdaging waar je tegenaan loopt.</p><p><strong>Aantekeningen voor de begeleider:</strong></p><ul><li>Ga eerst naar het model voor kwetsbaarheid.</li><li>Houd de introducties kort (1 minuut per persoon).</li><li>Merk de gemeenschappelijke thema&#39;s op.</li><li>Valideer alle antwoorden</li></ul><hr><h4 id="deel-2-de-zone-flowtoestand-40-minuten" tabindex="-1">Deel 2: De zone-/flowtoestand (40 minuten) <a class="header-anchor" href="#deel-2-de-zone-flowtoestand-40-minuten" aria-label="Permalink to &quot;Deel 2: De zone-/flowtoestand (40 minuten)&quot;">​</a></h4><p><strong>Doelstellingen:</strong></p><ul><li>Begrijp flowtoestanden</li><li>Onderscheid de technische modus versus de flowmodus.</li><li>Leer het &quot;schakelaar&quot;-concept.</li></ul><p><strong>Openingsvraag:</strong> &quot;Denk eens terug aan een moment waarop je je beste pétanque speelde. Hoe voelde dat? Wat was er anders?&quot;</p><p><strong>Discussievragen:</strong></p><ol><li>&quot;Hoeveel van jullie hebben wel eens een wedstrijd gespeeld waarbij alles gewoon op zijn plek viel?&quot;</li><li>&quot;Waar dacht je aan tijdens die momenten?&quot;</li><li>&quot;Wat is het verschil met de situatie waarin je het moeilijk hebt?&quot;</li></ol><p><strong>Belangrijkste leerpunten:</strong></p><p>Gebruik het whiteboard om te tekenen:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Oefening: De Omschakeling (10 minuten)</strong></p><p>&quot;Laten we het omschakelingsmoment oefenen:</p><ol><li>Sta op</li><li>Stel je voor dat je buiten de cirkel staat - denk aan een slag.</li><li>Haal even diep adem.</li><li>Stap naar voren (in een denkbeeldige cirkel)</li><li>Laat bij elke stap de analyse los.</li><li>Richt je uitsluitend op een denkbeeldig doelwit.</li></ol><p><strong>Nabespreking:</strong></p><ul><li>&quot;Wat viel je op?&quot;</li><li>&quot;Was het makkelijk of moeilijk om het denken los te laten?&quot;</li><li>&quot;Hoe zou dit in de praktijk bij echte wedstrijden toegepast kunnen worden?&quot;</li></ul><hr><h4 id="deel-3-pauze-10-minuten" tabindex="-1">Deel 3: Pauze (10 minuten) <a class="header-anchor" href="#deel-3-pauze-10-minuten" aria-label="Permalink to &quot;Deel 3: Pauze (10 minuten)&quot;">​</a></h4><p><strong>Acties van de begeleider:</strong></p><ul><li>Stimuleer informele discussies.</li><li>Merk groepsenergie op</li><li>Bereid je voor op het volgende onderdeel.</li></ul><hr><h4 id="deel-4-de-innerlijke-criticus-40-minuten" tabindex="-1">Deel 4: De innerlijke criticus (40 minuten) <a class="header-anchor" href="#deel-4-de-innerlijke-criticus-40-minuten" aria-label="Permalink to &quot;Deel 4: De innerlijke criticus (40 minuten)&quot;">​</a></h4><p><strong>Doelstellingen:</strong></p><ul><li>Negatieve zelfspraakpatronen herkennen</li><li>Onderscheid de innerlijke criticus van de innerlijke coach.</li><li>Oefen neutrale observatie.</li></ul><p><strong>Opening:</strong> &quot;We hebben allemaal een innerlijke stem die commentaar levert op onze prestaties. Soms is die stem behulpzaam, soms is ze hard. Laten we die eens onderzoeken.&quot;</p><p><strong>Oefening: Inventarisatie van je innerlijke criticus (15 minuten)</strong></p><p>Schrijf op je papier het volgende op:</p><ol><li>Wat je innerlijke stem zegt na een mislukte worp.</li><li>Wat het zegt als je onder druk staat</li><li>Wat het zegt over jouw vaardigheden.</li></ol><p><em>Neem 5 minuten de tijd om te schrijven</em></p><p>&quot;Wie wil er nu een voorbeeld geven?&quot;</p><p><strong>Aantekeningen voor de begeleider:</strong></p><ul><li>Normaliseer harde zelfpraat.</li><li>Probeer niemand te &quot;verbeteren&quot;.</li><li>Zoek naar gemeenschappelijke patronen.</li></ul><p><strong>Les: De innerlijke criticus versus de innerlijke coach (15 minuten)</strong></p><p>Teken twee kolommen op het whiteboard:</p><table tabindex="0"><thead><tr><th>Innerlijke criticus</th><th>Innerlijke coach</th></tr></thead><tbody><tr><td>&quot;Hoe kon je dat nou missen?!&quot;</td><td>&quot;Dat ging naar links&quot;</td></tr><tr><td>&quot;Je faalt altijd&quot;</td><td>&quot;Laten we het nog eens proberen&quot;</td></tr><tr><td>&quot;Je bent vreselijk&quot;</td><td>&quot;Wat kan ik leren?&quot;</td></tr></tbody></table><p><strong>Discussie:</strong></p><ul><li>&quot;Zie je het verschil?&quot;</li><li>&quot;Welke stem bevordert de prestatie?&quot;</li><li>&quot;Kun je de stem veranderen?&quot;</li></ul><p><strong>Oefening: Herkaderen (10 minuten)</strong></p><p>&quot;Neem een uitspraak van je innerlijke criticus. Hoe zou een innerlijke coach die formuleren?&quot;</p><p>Deel voorbeelden.</p><hr><h4 id="deel-5-praktische-hulpmiddelen-40-minuten" tabindex="-1">Deel 5: Praktische hulpmiddelen (40 minuten) <a class="header-anchor" href="#deel-5-praktische-hulpmiddelen-40-minuten" aria-label="Permalink to &quot;Deel 5: Praktische hulpmiddelen (40 minuten)&quot;">​</a></h4><p><strong>Doelstellingen:</strong></p><ul><li>Leer de 3-ademhaling reset.</li><li>Stel een eenvoudige routine op vóór de opname.</li><li>Inzicht in foutcorrectie</li></ul><p><strong>Hulpmiddel 1: Reset met 3 ademhalingen (10 minuten)</strong></p><p>&quot;Dit is je noodresetknop. Gebruik hem als je de druk voelt oplopen.&quot;</p><p><strong>Tonen:</strong></p><ol><li>Adem in gedurende 4 tellen.</li><li>Houd 2 tellen vast</li><li>Adem 6 tellen uit.</li><li>Herhaal dit 3 keer.</li></ol><p>&quot;Laten we nu samen oefenen.&quot;</p><p><em>Begeleid de groep door 3 cycli</em></p><p><strong>Nabespreking:</strong></p><ul><li>&quot;Wat merkte je aan je lichaam?&quot;</li><li>&quot;Wanneer zou je dit kunnen gebruiken?&quot;</li></ul><p><strong>Tool 2: Eenvoudige voorbereidingsroutine (15 minuten)</strong></p><p>&quot;Een routine helpt je om consistent over te schakelen van planning naar uitvoering.&quot;</p><p><strong>Basisstructuur:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Oefening:</strong> &quot;Ontwerp je eigen routine van 3 stappen. Schrijf deze op.&quot;</p><p>Deel voorbeelden.</p><p><strong>Hulpmiddel 3: Protocol voor foutcorrectie (15 minuten)</strong></p><p>&quot;Topspelers maken niet minder fouten. Ze herstellen sneller.&quot;</p><p><strong>3-stappenprotocol:</strong></p><ol><li><strong>Observeer</strong> - Geef de feitelijke situatie neutraal weer (&quot;Dat ging naar links&quot;).</li><li><strong>Leren</strong> - Informatie extraheren (&quot;Wind sterker dan ik dacht&quot;)</li><li><strong>Reset</strong> - Ga vooruit (3 ademhalingen, blik vooruit)</li></ol><p><strong>Oefening:</strong> &quot;Denk aan een recente fout. Doorloop de 3 stappen.&quot;</p><hr><h4 id="deel-6-integratie-en-afsluiting-20-minuten" tabindex="-1">Deel 6: Integratie en afsluiting (20 minuten) <a class="header-anchor" href="#deel-6-integratie-en-afsluiting-20-minuten" aria-label="Permalink to &quot;Deel 6: Integratie en afsluiting (20 minuten)&quot;">​</a></h4><p><strong>Doelstellingen:</strong></p><ul><li>Consolideer het leerproces</li><li>Stel actieplannen op</li><li>Zorg voor de benodigde middelen</li></ul><p><strong>Reflectievragen:</strong></p><ol><li>&quot;Wat is één belangrijk inzicht dat je hebt opgedaan?&quot;</li><li>&quot;Wat ga je deze week proberen?&quot;</li><li>&quot;Welke vragen blijven er nog over?&quot;</li></ol><p><strong>Actieplanning (10 minuten)</strong></p><p>&quot;Schrijf op uw werkblad:</p><ol><li>Een techniek die je deze week gaat oefenen.</li><li>Wanneer/waar ga je het oefenen?</li><li>Hoe je je voortgang bijhoudt</li></ol><p><strong>Bronnen:</strong></p><ul><li>Deel het samenvattingsblad uit.</li><li>Deel de website: carreau.app</li><li>Aanbevolen startmodule: <a href="/en/education/the-zone/">The Zone</a></li></ul><p><strong>Afsluitende kring:</strong> &quot;Eén woord om te beschrijven hoe je je nu voelt.&quot;</p><p><strong>Tot slot:</strong> &quot;Mentale training is een vaardigheid zoals elke andere - het vergt oefening. Begin klein, wees geduldig met jezelf en let op wat er verandert. Bedankt voor je openheid vandaag.&quot;</p><hr><h3 id="tips-voor-begeleiders" tabindex="-1">Tips voor begeleiders <a class="header-anchor" href="#tips-voor-begeleiders" aria-label="Permalink to &quot;Tips voor begeleiders&quot;">​</a></h3><h4 id="omgaan-met-moeilijke-situaties" tabindex="-1">Omgaan met moeilijke situaties <a class="header-anchor" href="#omgaan-met-moeilijke-situaties" aria-label="Permalink to &quot;Omgaan met moeilijke situaties&quot;">​</a></h4><p><strong>Als iemand de overhand heeft:</strong></p><ul><li>&quot;Dankjewel [naam]. We horen graag van anderen.&quot;</li><li>Gebruik gestructureerde beurtwisseling.</li></ul><p><strong>Als iemand zich verzet:</strong></p><ul><li>Ga niet in discussie</li><li>&quot;Dat is een terecht standpunt. Wat vinden anderen ervan?&quot;</li><li>Deel hun bezorgdheid</li></ul><p><strong>Als iemand emotioneel wordt:</strong></p><ul><li>Normaliseer het</li><li>&quot;Dit raakt me echt. Bedankt voor het delen.&quot;</li><li>Probeer het niet te repareren.</li></ul><p><strong>Als de discussie vastloopt:</strong></p><ul><li>Gebruik specifieke aanwijzingen.</li><li>Deel je eigen voorbeeld.</li><li>Ga naar een oefening</li></ul><h4 id="energiebeheer" tabindex="-1">Energiebeheer <a class="header-anchor" href="#energiebeheer" aria-label="Permalink to &quot;Energiebeheer&quot;">​</a></h4><p><strong>Hoog energieniveau:</strong> Gebruik oefeningen en beweging. <strong>Lage energie:</strong> Stel prikkelende vragen. <strong>Verspreid:</strong> Terugbrengen naar de structuur <strong>Tijdsvorm:</strong> Gebruik humor of breek de tijd af.</p><h3 id="na-de-sessie-1" tabindex="-1">Na de sessie <a class="header-anchor" href="#na-de-sessie-1" aria-label="Permalink to &quot;Na de sessie&quot;">​</a></h3><p><strong>Vervolgactie:</strong></p><ul><li>Stuur binnen 24 uur een samenvattende e-mail.</li><li>Voeg links naar bronnen toe.</li><li>Bied aan om vragen te beantwoorden</li><li>Plan een optionele vervolgsessie in.</li></ul><p><strong>Zelfreflectie:</strong></p><ul><li>Wat werkte goed?</li><li>Wat zou je veranderen?</li><li>Wat heeft je verrast?</li><li>Wat heb je geleerd?</li></ul><hr><h2 id="materialen" tabindex="-1">Materialen <a class="header-anchor" href="#materialen" aria-label="Permalink to &quot;Materialen&quot;">​</a></h2><ul><li><a href="/en/mental-journey/materials#participant-guide">Deelnemershandleiding</a></li><li><a href="/en/mental-journey/materials#facilitator-slides">Facilitator Slides</a></li><li><a href="/en/mental-journey/materials#summary-sheet">Samenvattingsblad</a></li><li><a href="/en/mental-journey/materials#exercise-worksheets">Oefenwerkbladen</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Klaar om te faciliteren?</p><ol><li>Lees deze handleiding aandachtig door.</li><li>Downloadmateriaal</li><li>Oefen de oefeningen zelf.</li><li>Plan je sessie in.</li><li>Vertrouw op het proces.</li></ol></div>',140))])}]]);export{u as __pageData,p as default};
